            '#anchor1',
            '/page1?age=42#anchor1',
            '?age=42#anchor1',
          ],
          anchors: ['anchor1'],
        },
      },
    });
  });

  it('accepts valid link with spaces and encoding', async () => {
    await testBrokenLinks({
      routes: [{path: '/page 1'}, {path: '/page 2'}],
      collectedLinks: {
